fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo and select the Lists application; the default 'Lists' (Browse) section opens. In the toolbar there is a view toggle offering table, card, and hierarchy layouts. Switch between at least two of these modes. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Success is that toggling the view mode visibly changes how the lists are laid out — e.g. a row/column table with Name/Entity/Items/Owner columns vs. a grid of cards vs. a folder-grouped hierarchy tree. (If the user has no lists, the 'No Lists Yet' empty state is a valid render.)",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The Lists browse section renders lists (in table, card, or hierarchy form) OR a valid 'No Lists Yet' empty state",
    "Activating a different view-toggle option changes the layout — the table columns, card grid, and hierarchy folder tree are visually distinct from one another",
    "No error messages, blank screens, or crash pages"
  ]
}
